 refs=['hodder-b22','ib-guide-b22']
 s['teachingBlocks']=[dict(title=t,explanation=e,referenceIds=refs) for t,e in bs]
 s['explanation']='\n\n'.join(e for t,e in bs)
 s['claimReferences']=[dict(claim=e,referenceIds=refs) for t,e in bs]
 s['scaffold']=scaffolds[i]
 s['textbook']['printedPages']=pages[i];s['textbook']['pdfPages']=[p+12 for p in pages[i]]
 s.pop('explorer',None)
 # Prediction precedes the explanation, and differs from the subsequent investigation/check.
 context=[
 'Two isolated fractions both show a mitochondrial enzyme signal. One also has high nuclear and lysosomal signals. Which evidence would make you more confident about a mitochondrial function?',
 'Imagine translating a newly copied eukaryotic RNA before an intron has been removed. What advantage could a nuclear boundary provide?',
 'A phagocyte needs to digest a bacterium without exposing all its cytosolic machinery to the same digestive conditions. What would a small membrane compartment provide?',
 'Two model mitochondria have equal inner-membrane area but different intermembrane volumes. The same extra amount of H+ is pumped into each. Where is the concentration increase greater?',
 'Light-driven electron transfer has accumulated H+ inside thylakoids. Which compartment should receive the H+ returning through ATP synthase?',
 'The nuclear envelope keeps chromosomes separate in interphase. Why might maintaining that boundary become a problem during open cell division?',
 'A pancreatic cell makes a cytosolic enzyme and an enzyme for secretion. Must it use permanently different kinds of ribosome?',
 'A secreted protein already exists when it reaches the Golgi. What could the Golgi still contribute?',
 'A membrane bends inward around external cargo. On which side should the proteins assembling its clathrin coat remain?'
 ][i]
 opts=[
 [('The fraction with fewer competing markers.',True,'That is a stronger starting inference because contaminants are less evident. You will test the limits of marker evidence.'),('Either fraction proves purity if the mitochondrial marker is present.',False,'A target marker establishes presence, not absence of other components.')],
 [('Time and space for RNA processing before ribosomes read the message.',True,'The key opportunity is processing before cytoplasmic translation. Track what crosses the boundary.'),('It lets ribosomes read DNA instead of RNA.',False,'Ribosomes translate mRNA. A boundary changes location and timing, not the molecule read by ribosomes.')],
 [('A local concentration of enzymes and a distinct internal environment.',True,'Containment can organize both the reactants and their working conditions. Test these benefits separately.'),('A place where no substances can ever enter or leave.',False,'The compartment must receive cargo and enzymes and eventually handle products. Controlled exchange matters.')],
 [('In the smaller volume.',True,'For the same net amount added, concentration increase equals amount divided by volume. The later model will show what this does and does not explain.'),('In the larger volume because it has more space.',False,'More volume dilutes the same added amount. Distinguish concentration from the total amount present.')],
 [('Stroma.',True,'Now explain how this flow can couple the thylakoid reactions to carbon fixation in the stroma.'),('Mitochondrial matrix.',False,'The matrix is a mitochondrial compartment. Keep the compartments of the two organelles distinct.')],
 [('The spindle needs access to chromosomes.',True,'Consider how the cell alternates selective exchange in interphase with wider access during division.'),('The DNA must leave to be translated.',False,'DNA is not translated. The relevant process is chromosome segregation.')],
 [('No; targeting information in the growing protein can direct ER association.',True,'The protein route depends on its targeting information. Compare where the ribosome sits and where the chain goes.'),('Yes; a free ribosome can never bind ER.',False,'Free and ER-bound describe locations during translation, not permanent ribosome species.')],
 [('Processing and sorting for a destination.',True,'The original polypeptide can be modified and packaged after translation. Follow the evidence in the pulse–chase activity.'),('Transcription of its gene.',False,'Transcription produces RNA from DNA and occurs in the nucleus for this gene, before translation and Golgi entry.')],
 [('On the cytosolic surface.',True,'Track the membrane faces as the bud closes. External cargo becomes lumenal while the coat stays cytosolic.'),('Inside the cargo-filled lumen.',False,'The coat is recruited by cytosolic machinery. Follow which side of the membrane it can contact.')]
 ][i]
 s['prediction']={'context':context,'question':{'id':f'b22-predict-{i+1}','kind':'selection','prompt':'Choose a starting prediction.','understandingIds':s['understandingIds'],'options':[dict(id=str(j),text=t,correct=c,feedback=f) for j,(t,c,f) in enumerate(opts)]}}
